INSERT INTO "public"."questions" ("id", "dimension", "dim_index", "question", "hint", "order_num", "created_at") VALUES ('039d17f4-c6a8-42b7-991d-0e7b326aa198', 'Value Recognition', 5, 'The way this organisation rewards people reflects what truly matters for success.', 'Reflect on alignment between what is valued and how people are rewarded.', 13, '2026-04-17 19:59:11.455207+00'), ('0721c145-fb8c-4c60-b3cb-6e1bedfcbcbd', 'Agility & Resilience', 10, 'When unexpected challenges occur, this organisation adapts quickly and effectively.', 'Think about how the organisation responds to disruption and change.', 22, '2026-04-17 19:59:11.455207+00'), ('1989e5ab-7fba-428c-abb8-f9b02b9fe5ee', 'Purpose & Meaning', 3, 'I understand how my work contributes to something bigger and more meaningful than just tasks.', 'Consider your sense of connection to the organisation purpose.', 8, '2026-04-17 19:59:11.455207+00'), ('28bb6fba-4680-4092-90a4-216bf0d7d077', 'Customer Orientation', 11, 'I clearly understand how my role contributes to delivering value to our customers.', 'Reflect on the connection between your work and customer outcomes.', 25, '2026-04-17 19:59:11.455207+00'), ('2a34feec-07b1-4f1e-a8b3-44027dad42eb', 'Execution Discipline', 2, 'People in this organisation are held accountable for delivering on their commitments.', 'Think about how accountability operates at all levels.', 7, '2026-04-17 19:59:11.455207+00'), ('2a5fde5e-2156-40ee-a0cc-c176054d1930', 'Decision Making', 4, 'Leaders in this organisation make decisions promptly, even when the situation is unclear.', 'Think about how decisively your organisation acts under pressure.', 10, '2026-04-17 19:59:11.455207+00'), ('44735fd9-395d-47b2-bad0-9dfacf14d31c', 'Innovation', 9, 'New ideas from any level of the organisation are genuinely welcomed and explored.', 'Reflect on how open and inclusive the innovation culture is.', 21, '2026-04-17 19:59:11.455207+00'), ('4dc668b7-a729-4a4a-b0a1-ec0f7a8b3195', 'Leadership Influence', 7, 'Leaders build genuine trust and use their influence to bring people along, not to control.', 'Consider the quality of leadership relationships and how leaders create followership.', 16, '2026-04-17 19:59:11.455207+00'), ('53792707-d5c9-4035-8678-aeaf8967e5e9', 'Systems Intelligence', 1, 'People in this organisation understand how their work connects to and affects other teams.', 'Consider whether silos exist and cross-functional collaboration is the norm.', 4, '2026-04-17 19:59:11.455207+00'), ('5d15c44a-8d67-490d-917e-d8a585871715', 'Psychological Safety', 8, 'People in this organisation feel safe to speak up, disagree, or raise problems without fear of consequences.', 'Think about the degree to which fear shapes how people communicate here.', 18, '2026-04-17 19:59:11.455207+00'), ('65af9d6a-7f60-4ef4-bfc6-54b8bc8818fb', 'Psychological Safety', 8, 'I can challenge a decision or raise a concern without worrying about how it will affect my reputation.', 'Reflect on your personal experience of psychological safety.', 19, '2026-04-17 19:59:11.455207+00'), ('7462b61b-e5b7-4094-96c6-bc2d4d9a7307', 'Listening & Learning', 6, 'When people raise concerns or ideas, they are genuinely listened to and taken seriously.', 'Think about how the organisation responds to feedback and input.', 14, '2026-04-17 19:59:11.455207+00'), ('775c53bc-f8b4-4e2b-a052-20c33b9710c9', 'Strategic Coherence', 0, 'Leaders make decisions that are consistent with our stated strategy and priorities.', 'Think about alignment between what leaders say and what they do.', 2, '2026-04-17 19:59:11.455207+00'), ('788177ba-63ff-406b-a442-3926f6b5a8a6', 'Execution Discipline', 2, 'When decisions are made, they are implemented effectively and without unnecessary delay.', 'Consider how consistently plans translate into action in your organisation.', 6, '2026-04-17 19:59:11.455207+00'), ('78cc4a4f-3511-4c6e-9c73-3947c589dc8d', 'Purpose & Meaning', 3, 'I feel proud to work for this organisation and what it stands for.', 'Reflect on your emotional connection to the organisation mission.', 9, '2026-04-17 19:59:11.455207+00'), ('7b278763-cef9-44e5-a7f8-da4a49b0eed6', 'Value Recognition', 5, 'All forms of contribution, including behind-the-scenes and relational work, are acknowledged and valued.', 'Consider whether the full range of value creation is recognised, not just visible output.', 12, '2026-04-17 19:59:11.455207+00'), ('9babdd21-a45f-4a66-8041-39f69877c239', 'Systems Intelligence', 1, 'We regularly share information across departments to avoid duplication and fragmentation.', 'Think about how well-connected different parts of the organisation are.', 5, '2026-04-17 19:59:11.455207+00'), ('b35c16d2-b94a-476a-ae29-739a17d77048', 'Listening & Learning', 6, 'This organisation learns from its mistakes and uses them to improve how it works.', 'Reflect on how errors and setbacks are treated.', 15, '2026-04-17 19:59:11.455207+00'), ('c638a067-7a6a-472f-967f-106294380887', 'Customer Orientation', 11, 'Decisions are consistently made through the lens of what is best for the customer.', 'Consider how central customer value is to daily decisions and operations.', 24, '2026-04-17 19:59:11.455207+00'), ('c9407536-51cf-43dc-be20-a18a66f42a4e', 'Strategic Coherence', 0, 'Our strategy translates into clear priorities that guide how I spend my time.', 'Reflect on whether strategic direction shapes your day-to-day work.', 3, '2026-04-17 19:59:11.455207+00'), ('cf035614-ade2-46ae-b106-c4738189f3e6', 'Agility & Resilience', 10, 'This organisation bounces back from setbacks without losing momentum or direction.', 'Reflect on the organisation resilience in the face of adversity.', 23, '2026-04-17 19:59:11.455207+00'), ('d2b45770-393b-4a23-9eae-bee7dabe94b3', 'Innovation', 9, 'This organisation actively encourages people to experiment with new approaches, even if they might fail.', 'Consider how risk-taking and experimentation are viewed and rewarded.', 20, '2026-04-17 19:59:11.455207+00'), ('e83f10dc-4e20-47d2-a29a-5345d5d9f061', 'Leadership Influence', 7, 'Leaders in this organisation are visible, accessible, and invested in the people they lead.', 'Reflect on the presence and quality of leadership connection.', 17, '2026-04-17 19:59:11.455207+00'), ('ea2b16b3-580c-473c-8cc8-ff986999531b', 'Decision Making', 4, 'People take responsibility for decisions rather than escalating everything upward.', 'Reflect on where decision-making authority sits and how it is exercised.', 11, '2026-04-17 19:59:11.455207+00'), ('fddaaa5c-dbd2-43e7-a68e-e2f01174a12d', 'Strategic Coherence', 0, 'I have a clear understanding of where this organisation is heading and what it is trying to achieve.', 'Consider how clearly direction, goals and strategy are communicated across the organisation.', 1, '2026-04-17 19:59:11.455207+00');


